begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000005440','pilot-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000005441','pilot-staff@example.test',now());
insert into auth.users(id,is_anonymous) values ('f0000000-0000-4000-8000-000000005442',true);
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005440","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Pilot test','weblink-pilot-test',gen_random_uuid())::text,true);
select set_config('test.other',create_tenant('Other pilot','weblink-pilot-other',gen_random_uuid())::text,true);
select set_config('test.printer',gen_random_uuid()::text,true);
select register_weblink_printer(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,'Pilot','',203);
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,gen_random_uuid(),true)$$,'%DEVICE_NOT_FOUND%','unpaired activation refused');
select set_config('test.code',create_print_pairing_code(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid)->>'code',true);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005442","role":"authenticated","is_anonymous":true}';
select set_config('test.device',pair_print_device(current_setting('test.code'),'Pilot bridge','test')->>'deviceId',true);
select throws_ok($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true)$$,'42501',null,'device cannot activate');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005440","role":"authenticated"}';
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,false)$$,'%INVALID_INPUT%','explicit pilot acknowledgement required');
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,null,null,true)$$,'%INVALID_INPUT%','null activation refused');
select throws_like($$select set_weblink_pilot(current_setting('test.other')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true)$$,'%PRINTER_NOT_FOUND%','cross-store printer refused');
select is(set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true),current_setting('test.printer')::uuid,'owner enables pilot');
select is((select active from printers where id=current_setting('test.printer')::uuid),true,'pilot active');
select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true);
select is((select count(*) from access_events where tenant_id=current_setting('test.tenant')::uuid and action='print.pilot_enabled'),1::bigint,'replay has one audit event');
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','pilot-seller@example.test','')::text,true);
select set_config('test.job',gen_random_uuid()::text,true);
select queue_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.printer')::uuid,'onboarding','zpl-v1','seller',current_setting('test.seller')::uuid,'^XA^FDPilot^FS^XZ',1);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005442","role":"authenticated","is_anonymous":true}';
select claim_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,gen_random_uuid());
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005440","role":"authenticated"}';
select is(set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,false,null,false),current_setting('test.printer')::uuid,'pause works during uncertain dispatch');
select is((select status from print_jobs where id=current_setting('test.job')::uuid),'dispatching','pause preserves dispatch evidence');
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true)$$,'%PRINT_OUTCOME_HELD%','unresolved work blocks activation');
select revoke_print_device(current_setting('test.tenant')::uuid,current_setting('test.device')::uuid);
select resolve_weblink_print_job(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'cancelled','Fixture inspected; no physical output');
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,true,current_setting('test.device')::uuid,true)$$,'%DEVICE_NOT_FOUND%','revoked device cannot reactivate');
select set_config('test.legacy',gen_random_uuid()::text,true);
select register_printer(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,'Legacy','tcp','192.0.2.1','',203);
select throws_like($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.legacy')::uuid,false,null,false)$$,'%PRINTER_NOT_FOUND%','legacy printer unchanged');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000005441','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000005441","role":"authenticated"}';
select throws_ok($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,false,null,false)$$,'42501',null,'staff cannot change pilot');
reset role;
update tenant_members set role='admin' where user_id='f0000000-0000-4000-8000-000000005441';
set local role authenticated;
select lives_ok($$select set_weblink_pilot(current_setting('test.tenant')::uuid,current_setting('test.printer')::uuid,false,null,false)$$,'admin may pause');
select throws_ok($$select set_weblink_pilot(current_setting('test.other')::uuid,current_setting('test.printer')::uuid,false,null,false)$$,'42501',null,'non-member refused');
reset role;
set local role anon;
select throws_ok($$select set_weblink_pilot(gen_random_uuid(),gen_random_uuid(),false,null,false)$$,'42501',null,'anonymous execution refused');
reset role;
select * from finish();
rollback;
